function fmtDur(t){
  t=Math.round((Number(t)||0)*10)/10;
  if(t<60)return t+'秒';
  const m=Math.floor(t/60);
  const s=Math.round((t-m*60)*10)/10;
  return m+'分'+(s?s+'秒':'');
}
function shotsOf(sc){return sc&&Array.isArray(sc.shots)?sc.shots:[];}
function totalOf(shots){
  let t=0;
  for(const x of shots){const n=Number(x.sec);if(isFinite(n)&&n>0)t+=n;}
  return t;
}
function K(el,tag,attrs,list){return el(tag,attrs,...list.filter(Boolean));}
function snap(d){
  return JSON.stringify([d.title,d.shots.map(x=>[x.id,x.visual,x.line,String(x.sec)])]);
}
function guard(c,fn){
  let p;
  try{p=fn();}catch(e){p=Promise.reject(e);}
  return Promise.resolve(p).catch(()=>{c.ui.saving=false;c.ui.err='保存失败，请稍后重试';c.redraw();});
}
function enterEdit(c,d,focusId,from){
  const ui=c.ui;
  d.base=snap(d);
  ui.draft=d;ui.view='detail';ui.from=from||'home';
  ui.focusShot=focusId?{id:focusId}:null;
  ui.err='';ui.confirmLeave=false;ui.delAsk=null;ui.saving=false;ui.sc={};
  c.redraw();
}
function openEdit(c,sc,focusId,from){
  const d={id:sc.id,title:sc.title||'',isNew:false,shots:shotsOf(sc).map(x=>({
    id:x.id,visual:x.visual||'',line:x.line||'',sec:x.sec>0?String(x.sec):''
  }))};
  enterEdit(c,d,focusId,from);
}
function startNew(c,from){
  const d={id:c.uid(),title:'',isNew:true,shots:[{id:c.uid(),visual:'',line:'',sec:''}]};
  enterEdit(c,d,null,from);
}
function mini(c,txt,label,dis,fn){
  const a={type:'button',class:'mini','aria-label':label,onclick:fn};
  if(dis)a.disabled=true;
  return c.el('button',a,txt);
}
function mount(ctx){
  const {root,state,ui}=ctx;
  const S=state&&Array.isArray(state.scripts)?state:{scripts:[],activeId:null};
  const active=S.scripts.find(x=>x.id===S.activeId)||S.scripts[0]||null;
  if(!ui.view||(ui.view==='detail'&&!ui.draft))ui.view='home';
  let node;
  if(ui.view==='detail')node=renderDetail(ctx,S);
  else if(ui.view==='scripts')node=renderScripts(ctx,S,active);
  else node=renderHome(ctx,S,active);
  root.append(node);
  const sc=root.querySelector('.scroll');
  if(sc){
    const key=ui.view;
    ui.sc=ui.sc||{};
    sc.scrollTop=ui.sc[key]||0;
    const f=ui.focusShot;
    if(f){
      const t=Array.from(sc.querySelectorAll('.shot')).find(z=>z.getAttribute('data-shot')===f.id);
      if(t){
        const top=t.offsetTop,bot=top+t.offsetHeight;
        if(top<sc.scrollTop+4)sc.scrollTop=Math.max(0,top-4);
        else if(bot>sc.scrollTop+sc.clientHeight)sc.scrollTop=bot-sc.clientHeight+4;
        const ta=t.querySelector('textarea');
        if(f.focus&&ta)ta.focus({preventScroll:true});
      }
      ui.focusShot=null;
    }
    ui.sc[key]=sc.scrollTop;
    sc.addEventListener('scroll',()=>{ui.sc[key]=sc.scrollTop;});
  }
}

function timeline(c,shots){
  const b=c.el('div',{class:'bar','aria-hidden':'true'});
  shots.forEach(x=>{
    const s=c.el('span',{class:'seg'});
    s.style.flexGrow=String(Math.max(Number(x.sec)||0,0.4));
    b.append(s);
  });
  return b;
}
function renderHome(c,S,active){
  const {el,ui,redraw}=c;
  const errBox=ui.err?el('div',{class:'err',role:'alert'},'⚠ '+ui.err):null;
  if(!active){
    return K(el,'div',{class:'home empty'},[
      el('div',{class:'eyebrow'},'视频脚本'),
      el('div',{class:'empty-t'},'还没有脚本'),
      el('div',{class:'empty-d'},'按镜头写画面、台词和大概秒数，还能调整镜头顺序。'),
      errBox,
      el('button',{type:'button',class:'btn primary',onclick:()=>startNew(c,'home')},'新建脚本')
    ]);
  }
  const shots=shotsOf(active);
  const total=totalOf(shots);
  const head=el('div',{class:'head'},
    el('div',{class:'eyebrow'},'当前脚本'),
    el('div',{class:'title'},active.title||'未命名脚本'),
    el('div',{class:'total'},
      el('span',{class:'tnum'},fmtDur(total)),
      el('span',{class:'tsub'},'总时长 · '+shots.length+' 个镜头')));
  const rows=shots.length?shots.map((x,i)=>
    el('button',{type:'button',class:'row',onclick:()=>openEdit(c,active,x.id,'home')},
      el('span',{class:'ix'},String(i+1)),
      K(el,'span',{class:'rt'},[
        el('span',{class:'rv'},x.visual||'（未写画面）'),
        x.line?el('span',{class:'rl'},'“'+x.line+'”'):null
      ]),
      el('span',{class:'rs'},x.sec>0?fmtDur(x.sec):'—'))
  ):[el('div',{class:'hint'},'还没有镜头，点“打开编辑”添加。')];
  const list=el('div',{class:'list scroll'},...rows);
  const actions=el('div',{class:'actions'},
    el('button',{type:'button',class:'btn primary',onclick:()=>openEdit(c,active,null,'home')},'打开编辑'),
    el('button',{type:'button',class:'btn',onclick:()=>{ui.view='scripts';ui.delScript=null;ui.err='';redraw();}},
      S.scripts.length>1?'切换脚本 '+S.scripts.length:'切换脚本'));
  return K(el,'div',{class:'home'},[head,shots.length?timeline(c,shots):el('div',{class:'bar empty-bar'}),list,errBox,actions]);
}

function shotCard(c,d,x,i,refresh){
  const {el,ui,redraw}=c;
  const n=d.shots.length;
  const mv=dir=>{
    const j=i+dir;
    if(j<0||j>=n)return;
    const t=d.shots[i];d.shots[i]=d.shots[j];d.shots[j]=t;
    ui.focusShot={id:x.id};ui.delAsk=null;redraw();
  };
  const del=()=>{
    const filled=!!(x.visual.trim()||x.line.trim()||String(x.sec).trim());
    if(filled&&ui.delAsk!==x.id){ui.delAsk=x.id;redraw();return;}
    d.shots.splice(i,1);ui.delAsk=null;redraw();
  };
  const secIn=el('input',{class:'sec',type:'number',inputmode:'decimal',min:'0',step:'any',value:x.sec,placeholder:'0',
    'aria-label':'第'+(i+1)+'个镜头的秒数',oninput:e=>{x.sec=e.target.value;refresh();}});
  const bump=k=>{
    const cur=Number(x.sec)||0;
    x.sec=String(Math.max(0,Math.round((cur+k)*10)/10));
    secIn.value=x.sec;refresh();
  };
  const ask=ui.delAsk===x.id;
  const node=el('div',{class:'shot'},
    el('span',{class:'ix'},String(i+1)),
    el('div',{class:'ctrl'},
      mini(c,'↑','上移',i===0,()=>mv(-1)),
      mini(c,'↓','下移',i===n-1,()=>mv(1)),
      ask?el('button',{type:'button',class:'mini ask',onclick:del},'确认删除'):mini(c,'✕','删除镜头',false,del)),
    el('label',{class:'f vis'},el('span',{class:'fl'},'画面'),
      el('textarea',{rows:'2',placeholder:'这个镜头拍什么',value:x.visual,oninput:e=>{x.visual=e.target.value;}})),
    el('label',{class:'f line'},el('span',{class:'fl'},'台词'),
      el('textarea',{rows:'2',placeholder:'旁白或对白，可留空',value:x.line,oninput:e=>{x.line=e.target.value;}})),
    el('div',{class:'secbox'},
      el('span',{class:'fl lab'},'大概'),
      mini(c,'−','减1秒',false,()=>bump(-1)),
      secIn,
      el('span',{class:'u'},'秒'),
      mini(c,'+','加1秒',false,()=>bump(1))));
  node.setAttribute('data-shot',x.id);
  return node;
}
function renderDetail(c,S){
  const {el,ui,redraw,commit,day,uid}=c;
  const d=ui.draft;
  const totalEl=el('b',{class:'tt'},fmtDur(totalOf(d.shots)));
  const refresh=()=>{totalEl.textContent=fmtDur(totalOf(d.shots));};
  const leave=()=>{
    ui.draft=null;ui.confirmLeave=false;ui.err='';
    ui.view=(ui.from==='scripts'&&S.scripts.length)?'scripts':'home';
    redraw();
  };
  const back=()=>{
    if(snap(d)!==d.base){ui.confirmLeave=true;redraw();}else leave();
  };
  const add=()=>{
    const id=uid();
    d.shots.push({id,visual:'',line:'',sec:''});
    ui.focusShot={id,focus:true};ui.delAsk=null;ui.err='';redraw();
  };
  const save=()=>{
    if(ui.saving)return;
    const title=d.title.trim();
    if(!title){ui.err='请先填写脚本名称';redraw();return;}
    const shots=[];
    for(let i=0;i<d.shots.length;i++){
      const x=d.shots[i];
      const v=x.visual.trim(),l=x.line.trim(),raw=String(x.sec).trim();
      if(!v&&!l&&!raw)continue;
      const n=raw===''?0:Number(raw);
      if(!isFinite(n)||n<0||n>86400){
        ui.err='第 '+(i+1)+' 个镜头的秒数不正确';ui.focusShot={id:x.id};redraw();return;
      }
      shots.push({id:x.id,visual:v,line:l,sec:Math.round(n*10)/10});
    }
    const rec={id:d.id,title,shots,updatedAt:day()};
    ui.saving=true;ui.err='';
    guard(c,()=>commit(s=>{
      const list=Array.isArray(s&&s.scripts)?s.scripts.slice():[];
      const k=list.findIndex(z=>z.id===rec.id);
      if(k>=0)list[k]=rec;else list.push(rec);
      return Object.assign({},s,{scripts:list,activeId:rec.id});
    },{view:'home',draft:null,err:'',saving:false,confirmLeave:false,from:'home'}));
  };
  const ti=el('input',{class:'ti',type:'text',value:d.title,maxlength:'40',placeholder:'脚本名称（必填）',
    'aria-label':'脚本名称',oninput:e=>{d.title=e.target.value;}});
  const saveAttrs={type:'button',class:'btn primary sm','aria-label':'保存脚本',onclick:save};
  if(ui.saving)saveAttrs.disabled=true;
  const hd=el('div',{class:'hd'},
    el('button',{type:'button',class:'icon','aria-label':'返回',onclick:back},'‹'),
    ti,
    el('button',saveAttrs,ui.saving?'保存中':'保存'));
  const sub=ui.confirmLeave
    ?el('div',{class:'leave'},
      el('span',{class:'subt wrap'},'有未保存的修改'),
      el('button',{type:'button',class:'btn sm',onclick:leave},'放弃修改'),
      el('button',{type:'button',class:'btn sm primary',onclick:()=>{ui.confirmLeave=false;redraw();}},'继续编辑'))
    :el('div',{class:'sub'},
      el('span',{class:'subt'},'总时长 ',totalEl,' · '+d.shots.length+' 镜头'),
      el('button',{type:'button',class:'btn sm',onclick:add},'＋ 镜头'));
  const errBox=ui.err?el('div',{class:'err',role:'alert'},'⚠ '+ui.err):null;
  const empty=d.shots.length?null:el('div',{class:'hint'},'还没有镜头，点下面的按钮添加。');
  const list=K(el,'div',{class:'scroll shots'},[
    ...d.shots.map((x,i)=>shotCard(c,d,x,i,refresh)),
    empty,
