function renderScripts(c,S,active){
  const {el,ui,redraw,update}=c;
  const back=()=>{ui.view='home';ui.delScript=null;ui.err='';redraw();};
  const pick=id=>{
    ui.view='home';ui.delScript=null;ui.err='';
    if(S.activeId===id){redraw();return;}
    guard(c,()=>update(s=>Object.assign({},s,{activeId:id})));
  };
  const remove=id=>{
    ui.delScript=null;
    guard(c,()=>update(s=>{
      const list=(Array.isArray(s&&s.scripts)?s.scripts:[]).filter(z=>z.id!==id);
      const keep=!!s&&s.activeId!==id&&list.some(z=>z.id===s.activeId);
      return Object.assign({},s,{scripts:list,activeId:keep?s.activeId:(list[0]?list[0].id:null)});
    }));
  };
  const hd=el('div',{class:'hd'},
    el('button',{type:'button',class:'icon','aria-label':'返回',onclick:back},'‹'),
    el('div',{class:'ht'},'切换脚本'),
    el('button',{type:'button',class:'btn sm',onclick:()=>startNew(c,'scripts')},'＋ 新建'));
  const rows=S.scripts.slice().reverse().map(sc=>{
    const on=!!active&&sc.id===active.id;
    const shots=shotsOf(sc);
    if(ui.delScript===sc.id){
      return el('div',{class:'srow ask'},
        el('div',{class:'asktxt'},'删除「'+sc.title+'」？删除后不能恢复。'),
        el('div',{class:'askbtns'},
          el('button',{type:'button',class:'btn sm primary',onclick:()=>remove(sc.id)},'确认删除'),
          el('button',{type:'button',class:'btn sm',onclick:()=>{ui.delScript=null;redraw();}},'取消')));
    }
    return el('div',{class:'srow'+(on?' on':'')},
      K(el,'button',{type:'button',class:'smain','aria-pressed':on?'true':'false',onclick:()=>pick(sc.id)},[
        el('span',{class:'st'},sc.title),
        el('span',{class:'sm'},fmtDur(totalOf(shots))+' · '+shots.length+' 镜头'+(sc.updatedAt?' · '+sc.updatedAt:'')),
        on?el('span',{class:'badge'},'使用中'):null
      ]),
      el('button',{type:'button',class:'icon','aria-label':'删除脚本「'+sc.title+'」',onclick:()=>{ui.delScript=sc.id;redraw();}},'✕'));
  });
  const errBox=ui.err?el('div',{class:'err',role:'alert'},'⚠ '+ui.err):null;
  const body=rows.length?rows:[el('div',{class:'hint'},'还没有保存过的脚本。')];
  return K(el,'div',{class:'detail'},[
    hd,
    el('div',{class:'sub'},el('span',{class:'subt'},'共 '+S.scripts.length+' 个脚本，点选一个设为当前')),
    errBox,
    el('div',{class:'scroll scripts'},...body)
  ]);
}

